def sqrt_int(n):
    """Return the integer square root of n: the largest integer whose
    square is <= n.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n

    lo, hi = 1, n
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return mid
        if sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

