python3 -c "
from sqrt_int import sqrt_int
for n in [0,1,4,9,144,9999999999999999**2]:
    r = sqrt_int(n)
    assert r*r == n and type(r) is int
    print(n if n<1000 else 'large perfect square', '->', r if r<1000 else 'ok')
try:
    sqrt_int(2)
except ValueError as e:
    print('sqrt_int(2) raises ValueError:', e)
try:
    sqrt_int(-1)
except ValueError as e:
    print('sqrt_int(-1) raises ValueError:', e)
